/**
 * The real ACP two-tone brand mark (AcpMark.tsx's exact SVG path data,
 * cream slash+C / orange P, transparent background), rasterized once via
 * sharp for embedding in the PDF report -- jsPDF has no native SVG
 * embedding, and this mark's path data is too complex to hand-replicate
 * with jsPDF's basic vector primitives. Same "generate once, commit as a
 * real asset" approach as embeddedFonts.ts.
 *
 * To regenerate: see the render script this was produced with (rasterizes
 * AcpMark.tsx's real path data at 1500x620px via sharp, matching the
 * mark's real 3750:1550 aspect ratio).
 */
export const ACP_LOGO_MARK_PNG = "data:image/png;base64,";
export const ACP_LOGO_MARK_ASPECT = 1500 / 620;
